export const BRAND_COLORS = {
  navyBg: '#101A39',
  navyText: '#121D42',
  navyStroke: '#10204D',
  ivoryBg: '#FBFBF4',
  limeAccent: '#CEEF62',
  slateLight: '#949EB9',
  slateDark: '#56607B',
  white: '#FFFFFF',
} as const;

export interface ThinkerMarkProps {
  size?: number;
  tone?: 'dark-bg' | 'light-bg' | 'lime-watermark';
  withRing?: boolean;
  className?: string;
}

export const ThinkerMark: React.FC<ThinkerMarkProps> = ({
  size = 40,
  tone = 'dark-bg',
  withRing = false,
  className,
}) => {
  const fill =
    tone === 'dark-bg'
      ? BRAND_COLORS.ivoryBg
      : tone === 'light-bg'
        ? BRAND_COLORS.navyBg
        : BRAND_COLORS.limeAccent;
  const ringStroke = tone === 'dark-bg' ? BRAND_COLORS.limeAccent : BRAND_COLORS.navyBg;
  const ringSize = Math.round(size * 1.43);

  return (
    <span
      className={className}
      style={{
        position: 'relative',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        width: withRing ? ringSize : size,
        height: withRing ? ringSize : size,
        flexShrink: 0,
      }}
    >
      {withRing && (
        <span
          aria-hidden="true"
          style={{
            position: 'absolute',
            inset: 0,
            borderRadius: '9999px',
            border: `1.5px solid ${ringStroke}`,
          }}
        />
      )}
      <svg
        viewBox="0 0 580 590"
        width={size}
        height={Math.round((size * 590) / 580)}
        aria-label="Isotipo Socratech"
        role="img"
      >
        <path d={THINKER_PATH_D} fill={fill} fillRule="evenodd" />
      </svg>
    </span>
  );
};

export interface EditorialDividerProps {
  width?: number | string;
  variant?: 'pill' | 'hairline';
  tone?: 'dark' | 'light';
}

export const EditorialDivider: React.FC<EditorialDividerProps> = ({
  width = 112,
  variant = 'pill',
  tone = 'dark',
}) => {
  if (variant === 'hairline') {
    return (
      <div
        className="st-divider-hairline"
        style={{
          backgroundColor: tone === 'dark' ? 'var(--st-ink-border)' : 'var(--st-border-light)',
        }}
      />
    );
  }
  return <div className="st-divider-pill" style={{ width }} />;
};

export interface EditorialTitleProps {
  eyebrow?: string;
  baseText: string;
  accentText: string;
  description?: string;
  tone?: 'dark' | 'light';
  size?: 'lg' | 'md';
  showDivider?: boolean;
}

export const EditorialTitle: React.FC<EditorialTitleProps> = ({
  eyebrow,
  baseText,
  accentText,
  description,
  tone = 'dark',
  size = 'lg',
  showDivider = true,
}) => {
  const fontSize = size === 'lg' ? 'clamp(28px, 3.2vw, 44px)' : 'clamp(22px, 2.2vw, 30px)';
  return (
    <div className={tone === 'dark' ? 'st-theme-dark' : 'st-theme-light'} style={{ background: 'transparent' }}>
      {eyebrow && (
        <div className="st-eyebrow" style={{ marginBottom: 10 }}>
          <span style={{ color: tone === 'dark' ? 'var(--st-accent)' : 'var(--st-ink-stroke)' }}>*</span>
          <span>{eyebrow}</span>
        </div>
      )}
      <h2
        style={{
          margin: 0,
          fontSize,
          lineHeight: 1.08,
          letterSpacing: '-0.03em',
          fontWeight: 700,
          color: tone === 'dark' ? 'var(--st-ink-fg)' : 'var(--st-ink-text)',
        }}
      >
        {baseText}{' '}
        <span className={tone === 'dark' ? 'st-display-lime-on-dark' : 'st-accent-pill-on-light'}>
          {accentText}
        </span>
      </h2>
      {showDivider && (
        <div style={{ marginTop: 14 }}>
          <EditorialDivider width={96} variant="pill" tone={tone} />
        </div>
      )}
      {description && (
        <p
          style={{
            marginTop: 12,
            marginBottom: 0,
            fontSize: 15,
            lineHeight: 1.55,
            color: tone === 'dark' ? 'var(--st-ink-muted)' : 'var(--st-muted-light)',
            maxWidth: 640,
          }}
        >
          {description}
        </p>
      )}
    </div>
  );
};

export interface OrbitMotifProps {
  size?: number;
  tone?: 'dark' | 'light';
  children?: React.ReactNode;
}

export const OrbitMotif: React.FC<OrbitMotifProps> = ({
  size = 180,
  tone = 'dark',
  children,
}) => {
  const outerBorder = tone === 'dark' ? 'var(--st-orbit-dark-outer)' : 'var(--st-orbit-light-outer)';
  const innerBorder = tone === 'dark' ? 'var(--st-orbit-dark-inner)' : 'var(--st-orbit-light-inner)';

  return (
    <div
      style={{
        position: 'relative',
        width: size,
        height: size,
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <div
        aria-hidden="true"
        style={{
          position: 'absolute',
          inset: 0,
          borderRadius: '9999px',
          border: `1.3px dashed ${outerBorder}`,
        }}
      />
      <div
        aria-hidden="true"
        style={{
          position: 'absolute',
          inset: '12%',
          borderRadius: '9999px',
          border: `1.3px solid ${innerBorder}`,
        }}
      />
      <span
        aria-hidden="true"
        style={{
          position: 'absolute',
          top: -4,
          left: '50%',
          transform: 'translateX(-50%)',
          width: 10,
          height: 10,
          borderRadius: '9999px',
          backgroundColor: 'var(--st-accent)',
          border: tone === 'light' ? '1.5px solid var(--st-ink-stroke)' : 'none',
        }}
      />
      {children}
    </div>
  );
};

export interface TechDiagramNode {
  tag: string;
  title: string;
  description: string;
  pill?: string;
}

export interface TechDiagramProps {
  nodes: TechDiagramNode[];
  consoleFilename?: string;
  consoleLines?: string[];
}

export const TechDiagram: React.FC<TechDiagramProps> = ({
  nodes,
  consoleFilename = 'pipeline.ts',
  consoleLines = [
    '// Socratech Motion Lab — Consola Socrática',
    'const status = await coordinator.dispatch(task);',
    '✓ Workspace aislado verificado',
  ],
}) => {
  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
          gap: 12,
        }}
      >
        {nodes.map((node) => (
          <div
            key={node.tag}
            className="st-card"
            style={{
              padding: 18,
              borderColor: 'var(--st-ink-stroke)',
              borderWidth: 1.5,
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
              <span
                style={{
                  fontFamily: 'var(--st-font-mono)',
                  fontSize: 11,
                  fontWeight: 700,
                  letterSpacing: '0.12em',
                  color: 'var(--st-muted-light)',
                }}
              >
                {node.tag}
              </span>
              {node.pill && (
                <span
                  style={{
                    backgroundColor: 'var(--st-accent)',
                    color: 'var(--st-accent-fg)',
                    border: '1px solid var(--st-ink-stroke)',
                    borderRadius: 9999,
                    padding: '2px 10px',
                    fontSize: 11,
                    fontWeight: 700,
                  }}
                >
                  {node.pill}
                </span>
              )}
            </div>
            <div style={{ fontWeight: 700, fontSize: 16, color: 'var(--st-ink-text)', marginBottom: 6 }}>
              {node.title}
            </div>
            <div style={{ fontSize: 13, lineHeight: 1.45, color: 'var(--st-muted-light)' }}>{node.description}</div>
          </div>
        ))}
      </div>
      <ConsoleBlock filename={consoleFilename} lines={consoleLines} />
    </div>
  );
};

