export const ConsoleBlock: React.FC<{ filename: string; lines: string[] }> = ({ filename, lines }) => (
  <div className="st-console">
    <div className="st-console-header">
      <div className="st-console-dots">
        <span className="st-console-dot" />
        <span className="st-console-dot" />
        <span className="st-console-dot st-console-dot--accent" />
      </div>
      <span>{filename}</span>
    </div>
    <pre style={{ margin: 0, padding: 16, fontSize: 12, lineHeight: 1.65, overflowX: 'auto' }}>
      {lines.map((line, i) => (
        <div
          key={i}
          style={{
            color: line.startsWith('✓')
              ? 'var(--st-accent)'
              : line.startsWith('//')
                ? 'var(--st-ink-muted)'
                : 'var(--st-ink-fg-pure)',
          }}
        >
          {line}
        </div>
      ))}
    </pre>
  </div>
);

export const StatusPill: React.FC<{ status: string }> = ({ status }) => {
  const normalized = status.toUpperCase();
  const styles: Record<string, { bg: string; fg: string; border: string }> = {
    COMPLETED: { bg: '#CEEF62', fg: '#101A39', border: '#10204D' },
    APPROVED: { bg: '#CEEF62', fg: '#101A39', border: '#10204D' },
    RUNNING: { bg: '#10204D', fg: '#CEEF62', border: '#CEEF62' },
    QUEUED: { bg: 'rgba(148, 158, 185, 0.18)', fg: '#121D42', border: '#949EB9' },
    INTERRUPTED: { bg: '#FFF3CD', fg: '#7A4F01', border: '#D39E00' },
    FAILED: { bg: '#FDE8E8', fg: '#C0392B', border: '#C0392B' },
    CANCELLED: { bg: 'rgba(86, 96, 123, 0.14)', fg: '#56607B', border: '#949EB9' },
  };
  const s = styles[normalized] ?? { bg: 'rgba(148, 158, 185, 0.18)', fg: '#121D42', border: '#949EB9' };
  return (
    <span
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        borderRadius: 9999,
        padding: '2px 10px',
        fontSize: 11,
        fontWeight: 700,
        letterSpacing: '0.06em',
        backgroundColor: s.bg,
        color: s.fg,
        border: `1px solid ${s.border}`,
      }}
    >
      {normalized}
    </span>
  );
};

